def normalize_language(language):
    return language if language in SUPPORTED_LANGUAGES else 'en'

def translate(message, language=None):
    language = normalize_language(language or normalize_language(session.get('language', 'en')))
    translated = TRANSLATIONS.get(message, {}).get(language)
    if translated:
        return translated
    if language == 'en':
        translated = message
        translated = re.sub(r'^Selamat datang, (.+)!$', r'Welcome, \1!', translated)
        translated = re.sub(r'^Cuti (.+) Anda tidak mencukupi\. Sisa: (\d+) hari\.$', r'Your \1 balance is insufficient. Remaining: \2 days.', translated)
        translated = re.sub(r'^Cuti (.+) disetujui', r'Leave for \1 approved', translated)
        translated = re.sub(r'^Cuti (.+) ditolak', r'Leave for \1 rejected', translated)
        translated = re.sub(r'^Level (\d+) disetujui - menunggu approval level (\d+)\.$', r'Level \1 approved, waiting for approval level \2.', translated)
        translated = re.sub(r'^Perusahaan (.+) berhasil ditambahkan!$', r'Company \1 added.', translated)
        translated = re.sub(r'^Perusahaan (.+) berhasil diperbarui!$', r'Company \1 updated.', translated)
        translated = re.sub(r'^Karyawan (.+) berhasil ditambahkan!$', r'Employee \1 added.', translated)
        translated = re.sub(r'^Karyawan (.+) berhasil diperbarui!$', r'Employee \1 updated.', translated)
        translated = re.sub(r'^Karyawan (.+) berhasil diarsipkan / dinonaktifkan\.$', r'Employee \1 archived / deactivated.', translated)
        translated = re.sub(r'^Karyawan (.+) berhasil dihapus permanen\.$', r'Employee \1 deleted permanently.', translated)
        translated = re.sub(r'^Karyawan (.+) berhasil diaktifkan kembali\.$', r'Employee \1 reactivated.', translated)
        translated = re.sub(r'^Karyawan (.+) berhasil dihapus\.$', r'Employee \1 deleted.', translated)
        translated = re.sub(r'^Jenis cuti (.+) berhasil ditambahkan!$', r'Leave type \1 added.', translated)
        translated = re.sub(r'^Jenis cuti (.+) berhasil diperbarui!$', r'Leave type \1 updated.', translated)
        translated = re.sub(r'^Jenis cuti (.+) berhasil diarsipkan\.$', r'Leave type \1 archived.', translated)
        translated = re.sub(r'^Jenis cuti (.+) berhasil dipulihkan dari arsip\.$', r'Leave type \1 restored from archive.', translated)
        translated = re.sub(r'^Departemen (.+) berhasil ditambahkan!$', r'Department \1 added.', translated)
        translated = re.sub(r'^Departemen (.+) berhasil diperbarui!$', r'Department \1 updated.', translated)
        translated = re.sub(r'^Departemen (.+) berhasil dihapus!$', r'Department \1 deleted.', translated)
        translated = re.sub(r'^Email uji coba berhasil dikirim ke (.+)! ✅$', r'Test email sent to \1! ✅', translated)
        translated = re.sub(r'^Gagal mengirim email test: (.+)$', r'Failed to send test email: \1', translated)
        return translated
    if language == 'idc':
        translated = message
        translated = re.sub(r'^Selamat datang, (.+)!$', r'Halo, \1!', translated)
        translated = re.sub(r'^Cuti (.+) Anda tidak mencukupi\. Sisa: (\d+) hari\.$', r'Saldo \1 kamu kurang. Sisa: \2 hari.', translated)
        translated = re.sub(r'^Level (\d+) disetujui - menunggu approval level (\d+)\.$', r'Level \1 approved, nunggu approval level \2.', translated)
        translated = re.sub(r'^Perusahaan (.+) berhasil ditambahkan!$', r'Company \1 udah ditambah.', translated)
        translated = re.sub(r'^Perusahaan (.+) berhasil diperbarui!$', r'Company \1 udah di-update.', translated)
        translated = re.sub(r'^Karyawan (.+) berhasil ditambahkan!$', r'Orang \1 udah ditambah.', translated)
        translated = re.sub(r'^Karyawan (.+) berhasil diperbarui!$', r'Orang \1 udah di-update.', translated)
        translated = re.sub(r'^Karyawan (.+) berhasil diarsipkan / dinonaktifkan\.$', r'Orang \1 udah diarsip / dinonaktifkan.', translated)
        translated = re.sub(r'^Karyawan (.+) berhasil dihapus permanen\.$', r'Orang \1 udah dihapus permanen.', translated)
        translated = re.sub(r'^Karyawan (.+) berhasil diaktifkan kembali\.$', r'Orang \1 udah diaktifin lagi.', translated)
        translated = re.sub(r'^Karyawan (.+) berhasil dihapus\.$', r'Orang \1 udah dihapus.', translated)
        translated = re.sub(r'^Jenis cuti (.+) berhasil ditambahkan!$', r'Tipe cuti \1 udah ditambah.', translated)
        translated = re.sub(r'^Jenis cuti (.+) berhasil diperbarui!$', r'Tipe cuti \1 udah di-update.', translated)
        translated = re.sub(r'^Jenis cuti (.+) berhasil diarsipkan\.$', r'Tipe cuti \1 udah diarsip.', translated)
        translated = re.sub(r'^Jenis cuti (.+) berhasil dipulihkan dari arsip\.$', r'Tipe cuti \1 udah dibalikin dari arsip.', translated)
        translated = re.sub(r'^Departemen (.+) berhasil ditambahkan!$', r'Divisi \1 udah ditambah.', translated)
        translated = re.sub(r'^Departemen (.+) berhasil diperbarui!$', r'Divisi \1 udah di-update.', translated)
        translated = re.sub(r'^Departemen (.+) berhasil dihapus!$', r'Divisi \1 udah dihapus.', translated)
        translated = re.sub(r'^Email uji coba berhasil dikirim ke (.+)! ✅$', r'Email test berhasil dikirim ke \1! ✅', translated)
        translated = re.sub(r'^Gagal mengirim email test: (.+)$', r'Gagal kirim email test: \1', translated)
        return translated
    return message
